package com.backendSupermercado.supermercasdo.modules.reportes.personal.repository;
import java.util.*; import org.springframework.data.domain.*; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository;
@Repository public class ReportePersonalRepository {private final NamedParameterJdbcTemplate jdbc;public ReportePersonalRepository(NamedParameterJdbcTemplate j){jdbc=j;}public Page<Map<String,Object>> consultar(String r,Map<String,Object>f,Pageable pg){MapSqlParameterSource p=new MapSqlParameterSource();f.forEach(p::addValue);String s,w=" WHERE 1=1 ",c;if(r.equals("empleados-general")){s="SELECT e.id_empleado AS id,CONCAT_WS(' ',pe.nombres,pe.apellido_paterno,pe.apellido_materno) AS empleado,ca.nombre AS cargo,e.estado";String from=" FROM empleado e JOIN persona pe ON pe.id_persona=e.id_persona LEFT JOIN contrato ct ON ct.id_empleado=e.id_empleado AND ct.estado='ACTIVO' LEFT JOIN cargo ca ON ca.id_cargo=ct.id_cargo ";return page(s+from+w+" ORDER BY empleado", "SELECT COUNT(*)"+from+w,p,pg);}if(r.equals("contratos-general")){s="SELECT ct.id,CONCAT_WS(' ',pe.nombres,pe.apellido_paterno,pe.apellido_materno) AS empleado,ca.nombre AS cargo,tc.nombre AS tipo,ct.fecha_inicio AS inicio,ct.fecha_fin AS fin,ct.sueldo_base AS sueldo,ct.estado";String from=" FROM contrato ct JOIN empleado e ON e.id_empleado=ct.id_empleado JOIN persona pe ON pe.id_persona=e.id_persona JOIN cargo ca ON ca.id_cargo=ct.id_cargo JOIN tipo_contrato tc ON tc.id_tipo_contrato=ct.id_tipo_contrato ";return page(s+from+w+" ORDER BY ct.fecha_inicio DESC","SELECT COUNT(*)"+from+w,p,pg);}String from=" FROM asistencia a JOIN contrato ct ON ct.id=a.id_contrato JOIN empleado e ON e.id_empleado=ct.id_empleado JOIN persona pe ON pe.id_persona=e.id_persona ";if(r.equals("asistencia-general")||r.equals("atrasos-inasistencias")||r.equals("horas-trabajadas")||r.equals("asistencias-justificadas")){if(r.equals("atrasos-inasistencias"))w+=" AND (a.minutos_retraso>0 OR a.estado='AUSENTE') ";if(r.equals("asistencias-justificadas"))w+=" AND a.tipo_justificacion IS NOT NULL ";s="SELECT a.id,a.fecha,CONCAT_WS(' ',pe.nombres,pe.apellido_paterno,pe.apellido_materno) AS empleado,a.estado,a.hora_entrada AS entrada,a.hora_salida AS salida,a.horas_trabajadas AS horas,a.minutos_retraso AS retraso,a.tipo_justificacion AS justificacion";return page(s+from+w+" ORDER BY a.fecha DESC","SELECT COUNT(*)"+from+w,p,pg);}from=" FROM solicitud_permiso sp JOIN empleado e ON e.id_empleado=sp.id_empleado JOIN persona pe ON pe.id_persona=e.id_persona JOIN tipo_permiso tp ON tp.id_tipo_permiso=sp.id_tipo_permiso JOIN estado_solicitud es ON es.id_estado_solicitud=sp.id_estado_solicitud ";s="SELECT sp.id,CONCAT_WS(' ',pe.nombres,pe.apellido_paterno,pe.apellido_materno) AS empleado,tp.nombre AS tipo,sp.fecha_inicio AS inicio,sp.fecha_fin AS fin,es.nombre AS estado";return page(s+from+w+" ORDER BY sp.fecha_inicio DESC","SELECT COUNT(*)"+from+w,p,pg);}private Page<Map<String,Object>>page(String s,String c,MapSqlParameterSource p,Pageable pg){p.addValue("limite",pg.getPageSize()).addValue("offset",pg.getOffset());List<Map<String,Object>>d=jdbc.queryForList(s+" LIMIT :limite OFFSET :offset",p);return new PageImpl<>(d,pg,jdbc.queryForObject(c,p,Long.class));}}
